class BubbleSort():
    def __init__(self, arr: list):
        self.raw = arr
        self.sorting = self.raw

    def sort(self):
        print(self.sorting)
        
        need_sort_len = len(self.sorting)
        for i in range(len(self.sorting)):
            for j in range(need_sort_len-1):
                if self.sorting[j] > self.sorting[j+1]:
                    self.sorting[j+1], self.sorting[j] = self.sorting[j], self.sorting[j+1]
                print(self.sorting)
        return self.sorting

    def check(self):
        prev = None
        for i in self.sorting:
            if prev is None: 
                prev = i
                continue
            if i < prev:
                return False
            prev = i

        return True

